{
  "root_causes": [
    {
      "service": "ts-travel-plan-service",
      "fault_kind": "http_response_body_corrupted",
      "evidence": [
        {"kind": "trace", "sql": "SELECT c.service_name callee, c.span_name, c.attr_http_response_status_code code, count(*) n FROM abnormal_traces p JOIN abnormal_traces c ON c.parent_span_id=p.span_id AND c.trace_id=p.trace_id WHERE p.service_name='ts-travel-plan-service' AND c.service_name='ts-seat-service' GROUP BY 1,2,3", "claim": "Travel-plan's seat calls in the incident hit 'POST /error' on seat-service and got 403 (239 calls)."},
        {"kind": "trace", "sql": "SELECT c.service_name callee, c.span_name, c.attr_http_response_status_code code, count(*) n FROM normal_traces p JOIN normal_traces c ON c.parent_span_id=p.span_id AND c.trace_id=p.trace_id WHERE p.service_name='ts-travel-plan-service' AND c.service_name='ts-seat-service' GROUP BY 1,2,3", "claim": "Normally the same travel-plan→seat calls go to POST /api/v1/seatservice/seats/left_tickets and return 200."},
        {"kind": "log", "sql": "SELECT service_name, level, substr(message,1,220) msg, count(*) c FROM abnormal_logs WHERE service_name='ts-travel-plan-service' AND level='SEVERE' GROUP BY 1,2,3", "claim": "Travel-plan logs SEVERE 'HttpClientErrorException$Forbidden: 403' for 239 requests during the incident."},
        {"kind": "trace", "sql": "SELECT span_name, attr_http_response_status_code code, attr_status_code, count(*) c FROM abnormal_traces WHERE service_name='ts-travel-plan-service' AND attr_status_code='Error' AND attr_http_response_status_code=500 GROUP BY 1,2,3", "claim": "Travel-plan's own travelPlan endpoints return 500 for minStation, cheapest and quickest requests after the 403s."}
      ]
    }
  ],
  "propagation": [
    {
      "from": "ts-travel-plan-service",
      "to": "ts-ui-dashboard",
      "evidence": [
        {"kind": "trace", "sql": "SELECT p.service_name caller, c.service_name callee, c.span_name, c.attr_http_response_status_code code, count(*) n FROM abnormal_traces p JOIN abnormal_traces c ON c.parent_span_id=p.span_id AND c.trace_id=p.trace_id WHERE p.service_name='ts-ui-dashboard' AND c.service_name='ts-travel-plan-service' GROUP BY 1,2,3,4 ORDER BY n DESC", "claim": "ui-dashboard's POST travelPlan calls to travel-plan return 500 for 228 requests, with about 9–12 s caller latency."}
      ]
    }
  ]
}
